// RUN-REC-BRIDGE-001 — WF-MON-001
// Grille 7 niveaux RECONSTRUITE faute de seuils historiques prouvés.
// Monitoring informatif et non bloquant.

const row = $input.first()?.json ?? {};

function toNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

const totalTokens = Math.max(0, Math.trunc(toNumber(row.total_tokens, 0)));
const requestCount = Math.max(0, Math.trunc(toNumber(row.request_count, 0)));

const averageTokensPerRequest =
  requestCount > 0
    ? Math.max(0, Math.trunc(toNumber(
        row.average_tokens_per_request,
        totalTokens / requestCount
      )))
    : 0;

const dailyBudget = 50000;

const usagePercent =
  dailyBudget > 0
    ? Number(((totalTokens / dailyBudget) * 100).toFixed(2))
    : 0;

let indicator;

if (usagePercent < 20) {
  indicator = {
    code: "green",
    label: "Faible",
    level: 1
  };
} else if (usagePercent < 40) {
  indicator = {
    code: "green-yellow",
    label: "Modérée",
    level: 2
  };
} else if (usagePercent < 60) {
  indicator = {
    code: "yellow",
    label: "Moyenne",
    level: 3
  };
} else if (usagePercent < 75) {
  indicator = {
    code: "yellow-orange",
    label: "Soutenue",
    level: 4
  };
} else if (usagePercent < 90) {
  indicator = {
    code: "orange",
    label: "Élevée",
    level: 5
  };
} else if (usagePercent < 100) {
  indicator = {
    code: "red-orange",
    label: "Très élevée",
    level: 6
  };
} else {
  indicator = {
    code: "red",
    label: "Budget atteint",
    level: 7
  };
}

let lastRequestAt = null;

if (row.last_request_at) {
  const d = new Date(row.last_request_at);

  if (!Number.isNaN(d.getTime())) {
    lastRequestAt = d.toISOString();
  }
}

return [{
  json: {
    ok: true,
    totalTokens,
    dailyBudget,
    usagePercent,
    indicator,
    usage: {
      requestCount,
      averageTokensPerRequest,
      lastRequestAt
    },
    overBudget: totalTokens > dailyBudget
  }
}];
